//! The lossless round-trip acceptance test: a real FreeCAD 1.0 document
//! (authored by `freecadcmd` r39109, then staged with the GUI-entry family
//! a GUI save carries — `GuiDocument.xml` + a stored thumbnail — and a
//! `SnellsLaw` constraint injected into the sketch's `<ConstraintList>`,
//! which the r39109 binary reads back exactly) survives a
//! **load → save** cycle with every non-regenerated byte intact.
//!
//! The fixture (`freecad_lossless_full.fcstd`) carries, in one archive:
//!
//! * an **imported STEP shape** as `Part::Feature` (`ImportedStep`) — an
//!   OCCT BRep payload (`ImportedStep.Shape.brp`) no parameter set can
//!   rebuild: the canonical data-loss case;
//! * a parametric `Part::Box` (`Base.Shape.brp`, rebuildable);
//! * a sketch with **construction geometry at GeoId 0** (the hole the
//!   reader's remap must invert), five real geometries after it, a
//!   `Block` constraint on the construction line and a `SnellsLaw`
//!   constraint referencing post-hole GeoIds;
//! * document metadata FreeCAD 1.0 writes (`Company`, `License`,
//!   `LicenseURL`, `Uid`, ...);
//! * FreeCAD's shape sidecars (`Base.Shape.brp`, `Sketch.Shape.brp`,
//!   `Sketch.InternalShape.brp`, `Sketch.Shape.Map.txt`);
//! * the GUI family (`GuiDocument.xml`, `Thumbnails/Thumbnail.png`).
//!
//! The contract under test — **lossless conversion**:
//!
//! 1. every archive entry the model does not regenerate re-emits
//!    byte-identically (payloads, GUI state, metadata);
//! 2. the document model itself loads (objects, links, sketch) and the
//!    re-saved file re-loads to the same content;
//! 3. the sketch's GeoId translation is inverted exactly — the written
//!    file references the ORIGINAL GeoIds, construction slot included;
//! 4. real FreeCAD 1.0 opens the re-saved file and sees the same
//!    document (verified with the r39109 binary while authoring this
//!    fixture: 3 objects, `ImportedStep.Volume == 7178.097245096173`,
//!    6 geometries / 9 constraints, `Company`/`License` intact — the
//!    numbers in the comments below).

use std::collections::BTreeMap;
use std::io::Read;
use std::path::PathBuf;

use fc_app::Document;
use fc_io::{load_document, save_document};

fn fixture_path(name: &str) -> PathBuf {
    let mut p = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    p.push("tests/fixtures");
    p.push(name);
    p
}

/// Every entry of a zip, name → bytes.
fn zip_entries(path: &std::path::Path) -> BTreeMap<String, Vec<u8>> {
    let file = std::fs::File::open(path).expect("fixture exists");
    let mut zip = zip::ZipArchive::new(file).expect("fixture is a zip");
    let mut out = BTreeMap::new();
    for i in 0..zip.len() {
        let mut entry = zip.by_index(i).expect("entry readable");
        let mut data = Vec::new();
        entry.read_to_end(&mut data).expect("entry readable");
        out.insert(entry.name().to_string(), data);
    }
    out
}

/// The first `<Constrain …/>` element of `xml` whose Type attribute equals
/// `ty` — the raw element as the file wrote it.
fn raw_constrain(xml: &str, ty: &str) -> String {
    let needle = format!("Type=\"{ty}\"");
    let start = xml
        .match_indices("<Constrain ")
        .map(|(i, _)| i)
        .find(|&i| {
            let end = i + xml[i..].find("/>").unwrap();
            xml[i..end].contains(&needle)
        })
        .unwrap_or_else(|| panic!("constraint Type={ty} present"));
    let end = start + xml[start..].find("/>").unwrap() + 2;
    xml[start..end].to_string()
}

#[test]
fn real_freecad_document_round_trips_losslessly() {
    let src = fixture_path("freecad_lossless_full.fcstd");
    let (doc, report) = load_document(&src).expect("real FreeCAD file loads");

    // --- The document model took what it models. -----------------------
    // (The imported STEP shape is OCCT BRep: not loadable as geometry —
    // but preserved. The Box and the sketch load; the construction
    // geometry and the SnellsLaw stay out of the solver and in the
    // sketch's preservation shadow.)
    assert_eq!(doc.object_count(), 3, "all three objects load");
    let base = doc.get_by_name("Base").expect("the Box loads");
    assert_eq!(base.type_name(), "Part::Box");
    let sketch = doc
        .get_by_name("Sketch")
        .expect("the sketch loads")
        .as_any()
        .downcast_ref::<fc_sketcher::SketchObject>()
        .expect("a SketchObject");
    // 5 modeled geometries (the construction line stays in the shadow).
    assert_eq!(sketch.sketch.geometry().len(), 5);
    // 7 modeled constraints: the Block on the construction line and the
    // SnellsLaw stay in the shadow (they reference/are constructs the
    // solver does not carry — preserved verbatim instead).
    assert_eq!(sketch.sketch.constraints().len(), 7);
    // The preservation shadow: construction slot 0, Block at position 7
    // and SnellsLaw at position 8, the file's counts.
    let preserved = sketch.preserved.as_ref().expect("shadow present");
    assert_eq!(preserved.geometry_count, 6);
    assert!(preserved.skipped_geometry.contains_key(&0), "construction kept");
    assert_eq!(preserved.constraint_count, 9);
    assert!(preserved.raw_constraints.contains_key(&7), "Block (on the construction line) kept");
    assert!(preserved.raw_constraints.contains_key(&8), "SnellsLaw kept");
    assert_eq!(preserved.geo_remap.len(), 6, "one remap slot per geometry");
    // The report is honest about the modeled gaps — as preservation.
    assert!(
        report
            .warnings
            .iter()
            .all(|w| fc_app::is_preservation_warning(w)),
        "every warning names a preservation, not a loss: {:?}",
        report.warnings
    );

    // --- The save + byte-level entry comparison. ------------------------
    let temp = std::env::temp_dir().join(format!(
        "fcrs-lossless-{}-{:?}.fcstd",
        std::process::id(),
        std::thread::current().id()
    ));
    save_document(&doc, &temp).expect("re-save works");
    let before = zip_entries(&src);
    let after = zip_entries(&temp);

    // Every entry the model does not regenerate is byte-identical:
    // the imported OCCT shape (the data-loss case this test exists
    // for), FreeCAD's own sidecars, the GUI family, the element map.
    for name in [
        "ImportedStep.Shape.brp",
        "Sketch.InternalShape.brp",
        "Sketch.Shape.brp",
        "Sketch.Shape.Map.txt",
        "GuiDocument.xml",
        "Thumbnails/Thumbnail.png",
    ] {
        assert_eq!(
            before.get(name),
            after.get(name),
            "entry '{name}' re-emits byte-identically"
        );
    }
    // FreeCAD's parametric Box payload also survives byte-identically:
    // until a recompute regenerates geometry from parameters (at which
    // point our own payload takes the entry), the file's copy of the
    // shape is the most truthful one — preservation keeps it.
    assert!(after.contains_key("Document.xml"), "the document is regenerated");
    assert_eq!(
        before.get("Base.Shape.brp"),
        after.get("Base.Shape.brp"),
        "the Box's file shape re-emits byte-identically until recompute"
    );

    // --- The regenerated Document.xml keeps the file's own facts. ------
    let xml = String::from_utf8(after["Document.xml"].clone()).expect("utf-8");
    let original_xml = String::from_utf8(before["Document.xml"].clone()).unwrap();
    // Document metadata (the modeled trio + preserved raws).
    assert!(xml.contains("payswap"), "Company survives");
    assert!(xml.contains("MIT"), "License survives");
    assert!(xml.contains("opensource.org/license/mit"), "LicenseURL survives");
    assert!(
        xml.matches("App::PropertyUUID").count() >= 1,
        "the Uid property element re-emits verbatim"
    );
    // The sketch's geometry list: 6 elements — 5 modeled (re-serialized
    // canonically) + the construction block at slot 0, verbatim.
    assert!(xml.contains(r#"<GeometryList count="6">"#), "geometry slots: 5 modeled + construction");
    let raw_construction = original_xml
        .match_indices("<Geometry ")
        .map(|(i, _)| i)
        .find(|&i| original_xml[i..].contains("StartX=\"-5"))
        .map(|i| {
            let end = i + original_xml[i..].find("</Geometry>").unwrap() + "</Geometry>".len();
            original_xml[i..end].to_string()
        })
        .expect("the construction line is in the original");
    assert!(
        xml.contains(&raw_construction),
        "the construction geometry block re-emits verbatim"
    );
    // The SnellsLaw constraint, verbatim.
    let raw_snells = raw_constrain(&original_xml, "16");
    assert!(
        xml.contains(&raw_snells),
        "the SnellsLaw constraint re-emits verbatim"
    );
    // GeoId inversion, the precise contract: the modeled constraints
    // reference the ORIGINAL file GeoIds — the construction hole at 0
    // stays a hole (Block on 0, coincidences over 1..4, radius on 5).
    let block = raw_constrain(&xml, "17");
    assert!(block.contains("First=\"0\""), "Block keeps the file's GeoId 0: {block}");
    let radius = raw_constrain(&xml, "11");
    assert!(radius.contains("First=\"5\""), "Radius keeps the file's GeoId 5: {radius}");
    let coincident = raw_constrain(&xml, "1");
    assert!(
        coincident.contains("First=\"1\"") && coincident.contains("Second=\"2\""),
        "Coincident keeps the file's GeoIds (1, 2): {coincident}"
    );

    // --- Reload: the re-saved file loads to the same content. ----------
    let (doc2, report2) = load_document(&temp).expect("re-saved file loads");
    let sketch2 = doc2
        .get_by_name("Sketch")
        .unwrap()
        .as_any()
        .downcast_ref::<fc_sketcher::SketchObject>()
        .unwrap();
    assert_eq!(sketch2.sketch.geometry().len(), 5);
    assert_eq!(sketch2.sketch.constraints().len(), 7);
    let preserved2 = sketch2.preserved.as_ref().expect("shadow reloads");
    assert!(preserved2.skipped_geometry.contains_key(&0));
    assert!(preserved2.raw_constraints.contains_key(&7));
    assert!(preserved2.raw_constraints.contains_key(&8));
    assert!(
        report2
            .warnings
            .iter()
            .all(|w| fc_app::is_preservation_warning(w)),
        "reload warnings are preservation notes: {:?}",
        report2.warnings
    );
}

/// A fresh document (no file shadow) saves without preservation entries —
/// the API-created path is exactly what it always was.
#[test]
fn fresh_document_saves_without_preservation_noise() {
    let mut doc = Document::new("fresh");
    let mut object = fc_part::features::BoxFeature::new("Box");
    object
        .container
        .set("Length", fc_app::Property::Float(3.0));
    doc.add(Box::new(object));
    doc.recompute_all().expect("recompute");

    let temp = std::env::temp_dir().join(format!(
        "fcrs-fresh-{}-{:?}.fcstd",
        std::process::id(),
        std::thread::current().id()
    ));
    save_document(&doc, &temp).expect("save");
    let (reloaded, report) = load_document(&temp).expect("reload");
    assert_eq!(reloaded.object_count(), 1);
    assert!(
        report.warnings.is_empty(),
        "a fresh file round-trips warning-free: {:?}",
        report.warnings
    );
}
